pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amountSeed) internal {
        vm.deal(address(c), VALUE_CAP);
        uint balBefore = address(c).balance;
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        uint callerBefore = address(this).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balAfter = address(c).balance;
        uint256 countAfter;
        try c.depositsCount() returns (uint256 __r) { countAfter = __r; } catch { return; }
        uint callerAfter = address(this).balance;
        assertTrue(!reverted
            && balAfter == 0
            && callerAfter == callerBefore + balBefore
            && countAfter == countBefore);
    }

    function testFuzz_run(uint256 amountSeed) public {
        _run(amountSeed);
    }

    receive() external payable {}
}
